-- Demo content for development (applied only with the dev and test profiles via classpath:db/demo).
-- Everything here is fictional placeholder content: the team, testimonials, prices, address and phone number
-- are invented, and the before/after images are demonstration crops, not patient results.
-- Photography is Unsplash placeholder imagery referenced by URL; replace it from the admin dashboard.

-- Builds a consistent Unsplash URL. pg_temp functions disappear with the migration session.
CREATE FUNCTION pg_temp.u(photo TEXT, w INT DEFAULT 1600, h INT DEFAULT NULL, faces BOOLEAN DEFAULT FALSE) RETURNS TEXT
    LANGUAGE sql IMMUTABLE AS
$$
SELECT 'https://images.unsplash.com/photo-' || photo || '?auto=format&fit=crop&w=' || w
           || CASE WHEN h IS NULL THEN '' ELSE '&h=' || h END
           || CASE WHEN faces THEN '&crop=faces' ELSE '' END
           || '&q=80'
$$;

