INSERT INTO treatment_categories (name, slug, description, display_order, active) VALUES
    ('Facial', 'facial', 'Considered facials that cleanse, hydrate and restore radiance, adapted to your skin on the day.', 1, TRUE),
    ('Advanced Skin', 'advanced-skin', 'Clinical resurfacing and renewal treatments, prescribed after a skin assessment.', 2, TRUE),
    ('Laser & Light', 'laser-light', 'Medical-grade laser and light technologies, always performed by trained practitioners.', 3, TRUE),
    ('Body', 'body', 'Non-invasive body treatments for contour, texture and firmness, paired with realistic goals.', 4, TRUE),
    ('Anti-Aging', 'anti-aging', 'Progressive protocols that support firmness and skin quality over time.', 5, TRUE),
    ('Skin Programs', 'skin-programs', 'Multi-session programs built around one concern and followed by the same specialist.', 6, TRUE);

INSERT INTO treatments (category_id, name, slug, short_description, description, duration_minutes, sessions, downtime,
                        price, price_from, benefits, preparation, aftercare, contraindications, technology,
                        main_image_url, main_image_alt, available, featured, created_at, updated_at)
SELECT c.id, v.name, v.slug, v.short_description, v.description, v.duration, v.sessions, v.downtime, v.price, v.price_from,
       v.benefits, v.preparation, v.aftercare, v.contraindications, v.technology, pg_temp.u(v.photo), v.alt,
       v.available, v.featured, now() - (v.age || ' days')::interval, now() - (v.age || ' days')::interval
FROM (VALUES
    ('facial', 'Signature Hydrafacial', 'signature-hydrafacial',
     'A three-step facial that cleanses, gently exfoliates and infuses hydrating serums, with no downtime.',
     'Our most requested facial. Using vortex technology, the treatment cleanses and gently exfoliates, extracts congestion without squeezing, then infuses serums chosen for your skin that day. Most clients leave with skin that looks fresher and feels comfortable, and can return to their day straight away.',
     60, 'Single session or monthly maintenance', 'None', 190.00, FALSE,
     E'Skin that looks clearer and more luminous\nGentle extraction of congestion\nHydration tailored to your skin on the day\nSuitable for most skin types',
     E'Avoid retinoids and exfoliating acids for 48 hours before\nArrive without heavy make-up if you can\nTell us about any recent treatments or new medication',
     E'Wear a broad-spectrum SPF 30 or higher\nAvoid saunas and intense exercise for 24 hours\nSkip exfoliating products for 48 hours',
     E'Active cold sores or skin infection in the area\nRecent facial surgery or laser treatment\nKnown allergy to any serum ingredient',
     'Hydrafacial vortex system', '1616394584738-fc6e612e71b9', 'Client relaxing during a hydrating facial', TRUE, TRUE, 120),
    ('facial', 'Facial Rejuvenation', 'facial-rejuvenation',
     'A sculpting facial combining manual lifting techniques with active serums for a rested, refined look.',
     'A slow, precise facial built around manual lifting and drainage techniques. Your practitioner works the facial muscles and connective tissue, then layers peptide and antioxidant serums. It is a treatment for skin that looks tired rather than a corrective procedure, and its effect is best maintained with regular sessions.',
     75, 'Every 3 to 4 weeks', 'None', 160.00, FALSE,
     E'A more rested, refreshed appearance\nSupports circulation and lymphatic flow\nRelaxes tension held in the jaw and forehead',
     E'Avoid sun exposure and self-tan for 48 hours before\nRemove contact lenses if you wear them',
     E'Drink water through the day\nAvoid heavy make-up for the rest of the day\nApply SPF every morning',
     E'Active skin infection or open lesions\nRecent injectable treatment (within 2 weeks)',
     'Manual facial sculpting, peptide serums', '1512290923902-8a9f81dc236c', 'Practitioner performing a manual facial', TRUE, FALSE, 118),
    ('facial', 'Deep Skin Cleansing', 'deep-skin-cleansing',
     'A thorough cleansing facial with steam, careful extraction and a calming mask for congested skin.',
     'Designed for skin prone to congestion and enlarged-looking pores. After a double cleanse and enzyme exfoliation, your therapist softens the skin with warm steam, performs careful extractions and finishes with a clay or calming mask depending on how your skin reacts.',
     60, 'Every 4 to 6 weeks', 'Possible mild redness for a few hours', 120.00, FALSE,
     E'Visibly clearer pores\nA smoother skin surface\nA calmer, more balanced complexion',
     E'Do not squeeze blemishes in the days before\nAvoid waxing or threading the face for 48 hours',
     E'Avoid make-up for 12 hours if possible\nKeep hands away from the face\nUse a gentle cleanser for 2 days',
     E'Active acne with painful inflamed lesions (a medical consultation is advised)\nRosacea flare-ups\nSunburn',
     'Enzyme exfoliation, steam, clay masks', '1570172619644-dfd03ed5d881', 'Mask being applied with a brush during a facial', TRUE, FALSE, 116),
    ('facial', 'Skin Hydration Ritual', 'skin-hydration-ritual',
     'An intensive moisture treatment for dehydrated, tight or sensitised skin, layered with hyaluronic serums.',
     'A comforting treatment for skin that feels tight or looks dull. Layers of hyaluronic acid, ceramides and a cooling hydrogel mask are applied in sequence while your therapist performs a soothing facial massage. Ideal before an event or after travel.',
     50, 'Single session or monthly', 'None', 140.00, FALSE,
     E'Skin that feels comfortable and supple\nA dewy, healthy-looking finish\nSoothes the feeling of tightness',
     E'No specific preparation needed\nLet us know if your skin is currently reactive',
     E'Keep using a gentle moisturiser morning and evening\nApply SPF daily',
     E'Known allergy to any product ingredient',
     'Hyaluronic acid and ceramide layering, hydrogel mask', '1599305090598-fe179d501227', 'Jar of hydrating cream on warm stone', TRUE, FALSE, 114),
    ('advanced-skin', 'Chemical Peels', 'chemical-peels',
     'Medical-grade peels, from gentle to deeper strengths, selected after a skin assessment.',
     'A chemical peel uses carefully selected acids to remove damaged surface cells and encourage renewal. We choose the formulation and strength after assessing your skin type, concerns and history. Lighter peels have little downtime; stronger peels may cause visible flaking for several days. Results build progressively and vary between individuals.',
     45, 'Course of 3 to 6, 2 to 4 weeks apart', '0 to 7 days depending on strength', 150.00, TRUE,
     E'Helps refine skin texture\nCan soften the look of pigmentation and fine lines\nSupports a more even tone over a course',
     E'A consultation is required before your first peel\nStop retinoids 5 to 7 days before\nAvoid sun exposure for 2 weeks before',
     E'Do not pick or peel flaking skin\nUse the post-peel kit as instructed\nStrict sun protection for 4 weeks',
     E'Pregnancy or breastfeeding\nIsotretinoin use in the past 6 months\nActive cold sores, eczema or broken skin in the area\nRecent tanning',
     'Glycolic, lactic, salicylic and TCA formulations', '1576426863848-c21f53c60b19', 'Dropper bottle of serum on white marble', TRUE, TRUE, 110),
    ('advanced-skin', 'Microneedling', 'microneedling',
     'Collagen induction therapy that creates controlled micro-channels to support skin renewal.',
     'Microneedling uses a sterile, single-use cartridge of fine needles to create controlled micro-channels in the skin. This prompts the skin’s own repair response, which can improve the look of texture, scarring and enlarged pores over a course of treatments. A topical anaesthetic keeps the treatment comfortable.',
     75, 'Course of 3 to 6, 4 to 6 weeks apart', '1 to 3 days of redness', 280.00, FALSE,
     E'Can soften the appearance of acne scarring\nHelps refine texture and pore appearance\nSupports firmer-looking skin over time',
     E'Consultation required before the first session\nStop retinoids and acids 5 days before\nAvoid blood-thinning supplements if your doctor agrees',
     E'No make-up for 24 hours\nAvoid sun, sauna and swimming for 72 hours\nUse only the recommended products for one week',
     E'Pregnancy\nActive acne, infection or cold sores\nKeloid scarring tendency\nBlood clotting disorders',
     'Medical microneedling device, single-use sterile cartridges', '1552693673-1bf958298935', 'Gloved practitioner treating a client’s skin', TRUE, TRUE, 108),
    ('advanced-skin', 'LED Light Therapy', 'led-light-therapy',
     'A painless light treatment using red and near-infrared wavelengths to calm and support the skin.',
     'Medical LED panels deliver specific wavelengths of light to the skin. Red and near-infrared light are used to support skin recovery and comfort, while blue light is used for blemish-prone skin. It is often added after peels or microneedling, or booked as a course on its own.',
     30, 'Course of 6 to 10, twice weekly', 'None', 80.00, FALSE,
     E'Comfortable and non-invasive\nSupports recovery after other treatments\nHelps calm visible redness',
     E'Arrive with clean skin\nTell us about any photosensitising medication',
     E'No special aftercare\nContinue your usual routine with SPF',
     E'Photosensitising medication\nEpilepsy triggered by light\nPregnancy (as a precaution)',
     'Medical-grade LED panels (415, 633 and 830 nm)', '1620916297397-a4a5402a3c6c', 'Hand holding a dropper of serum', TRUE, FALSE, 106),
    ('advanced-skin', 'Dermaplaning', 'dermaplaning',
     'Gentle manual exfoliation that removes dead surface cells and fine vellus hair for a smooth finish.',
     'Using a sterile surgical blade held at a careful angle, your therapist removes the outer layer of dead cells and fine facial hair. The result is skin that feels smooth and lets make-up and skincare sit more evenly. It is often combined with a hydrating mask.',
     40, 'Every 4 weeks', 'None', 110.00, FALSE,
     E'Immediately smoother-feeling skin\nRemoves fine vellus hair\nHelps skincare absorb evenly',
     E'Avoid retinoids for 3 days before\nNo waxing in the area for a week before',
     E'SPF every day\nAvoid exfoliating products for 3 days',
     E'Active acne or inflamed skin\nRecent sunburn\nCold sores',
     'Sterile single-use surgical blade', '1620916566398-39f1143ab7be', 'Tube of skincare resting on soft linen', TRUE, FALSE, 104),
    ('laser-light', 'Laser Hair Removal', 'laser-hair-removal',
     'Long-term hair reduction with a medical diode laser, adapted to your skin and hair type.',
     'Our diode laser targets the pigment in the hair follicle to reduce regrowth over a course of sessions. Settings are adapted to your skin tone and hair type after a patch test. Most people need several sessions because hair grows in cycles; results vary and occasional maintenance may be needed.',
     30, 'Course of 6 to 8, 4 to 8 weeks apart', 'Mild redness for a few hours', 90.00, TRUE,
     E'Long-term reduction of unwanted hair\nSuitable for most body areas\nFewer ingrown hairs for many clients',
     E'Patch test at least 48 hours before the first session\nShave the area the day before\nNo waxing, plucking or tanning for 4 weeks before',
     E'Avoid sun exposure on the area for 2 weeks\nNo hot baths or sauna for 24 hours\nApply a soothing gel if needed',
     E'Pregnancy\nTanned skin or recent self-tan\nPhotosensitising medication\nActive skin infection in the area',
     'Medical diode laser 810 nm with contact cooling', '1540555700478-4be289fbecef', 'Clean white bottle and folded towel', TRUE, FALSE, 102),
    ('laser-light', 'Laser Skin Resurfacing', 'laser-skin-resurfacing',
     'Fractional laser resurfacing for texture, fine lines and scarring, performed by our medical team.',
     'Fractional laser treats a fraction of the skin in microscopic columns, leaving surrounding tissue intact to speed recovery. It is used to improve the appearance of texture, fine lines and some scarring. This is a medical procedure: it is always preceded by a consultation with one of our physicians, and downtime should be planned.',
     60, '1 to 3 sessions, 6 to 8 weeks apart', '5 to 7 days of redness and flaking', 450.00, TRUE,
     E'Can noticeably refine skin texture\nMay soften fine lines and some scars\nResults continue to develop over several months',
     E'Medical consultation required\nAntiviral medication may be prescribed if you are prone to cold sores\nNo sun exposure or tanning for 4 weeks before',
     E'Follow the written aftercare plan provided\nStrict sun avoidance and SPF 50 for 8 weeks\nNo make-up until the skin has healed',
     E'Pregnancy or breastfeeding\nIsotretinoin use in the past 12 months\nHistory of keloid scarring\nActive skin infection',
     'Fractional non-ablative laser', '1631729371254-42c2892f0e6e', 'Minimal white skincare bottles on a warm surface', TRUE, FALSE, 100),
    ('laser-light', 'IPL Photorejuvenation', 'ipl-photorejuvenation',
     'Intense pulsed light to soften the look of sun spots, redness and uneven tone.',
     'IPL delivers broad-spectrum light that is absorbed by pigment and visible blood vessels. Over a short course it can help even out the appearance of sun damage and redness on the face, neck and hands. Treated spots often darken briefly before fading.',
     40, 'Course of 3 to 5, 4 weeks apart', 'Darkening of spots for 7 to 10 days', 250.00, TRUE,
     E'Helps even out skin tone\nCan reduce the look of sun spots and redness\nTreats face, neck, décolleté and hands',
     E'No sun exposure or tanning for 4 weeks before\nStop photosensitising products as advised',
     E'Do not scratch darkened spots\nStrict SPF 50 for 4 weeks\nAvoid heat for 48 hours',
     E'Tanned or darker skin types (assessed in consultation)\nPregnancy\nPhotosensitising medication',
     'Intense pulsed light platform with filters', '1515377905703-c4788e51af15', 'Hands applying drops of facial oil', TRUE, FALSE, 98),
    ('body', 'Body Contouring', 'body-contouring',
     'Non-invasive contouring combining radiofrequency and vacuum therapy for targeted areas.',
     'A non-surgical treatment that combines radiofrequency heat with vacuum massage on areas such as the abdomen, flanks and thighs. It can improve the look of contour and skin firmness over a course of sessions when combined with a balanced lifestyle. It is not a weight-loss treatment.',
     45, 'Course of 6 to 8, weekly', 'None', 220.00, TRUE,
     E'Non-invasive, no recovery time\nCan improve the look of contour and firmness\nComfortable warming sensation',
     E'Drink plenty of water the day before\nAvoid heavy meals 2 hours before',
     E'Keep hydrated\nLight exercise helps support results',
     E'Pregnancy\nPacemaker or metal implants in the area\nActive cancer treatment',
     'Radiofrequency with vacuum therapy', '1519823551278-64ac92734fb1', 'Therapist performing a body treatment', TRUE, TRUE, 96),
    ('body', 'Cellulite Treatment', 'cellulite-treatment',
     'A targeted protocol to smooth the appearance of cellulite with mechanical massage and radiofrequency.',
     'Cellulite is common and influenced by genetics, hormones and lifestyle. Our protocol combines mechanical lymphatic massage with radiofrequency to improve circulation and smooth the appearance of dimpling. Visible improvement varies and is best maintained with periodic sessions.',
     50, 'Course of 8 to 10, once or twice weekly', 'None', 180.00, FALSE,
     E'Smoother-looking skin surface\nSupports circulation and drainage\nRelaxing, massage-like sensation',
     E'Wear comfortable clothing\nAvoid caffeine on the day',
     E'Drink water through the day\nKeep moving with light activity',
     E'Pregnancy\nVaricose veins or venous disorders in the area\nRecent surgery in the area',
     'Mechanical endermology and radiofrequency', '1544161515-4ab6ce6db874', 'Oil being applied during a body treatment', TRUE, FALSE, 94),
    ('body', 'Body Sculpting', 'body-sculpting',
     'Electromagnetic muscle stimulation to support muscle tone in the abdomen, buttocks and arms.',
     'High-intensity electromagnetic stimulation causes deep muscle contractions that you cannot achieve voluntarily. Over a course, this can support muscle tone and definition. Sessions are performed lying down and feel like an intense workout. Results vary and are best supported by regular exercise.',
     30, 'Course of 4 to 6, 2 to 3 days apart', 'Possible muscle soreness', 240.00, TRUE,
     E'Supports muscle tone and definition\nNo recovery time\nShort sessions',
     E'Remove metal jewellery and electronics\nWear comfortable clothing',
     E'Stay hydrated\nGentle stretching if muscles feel sore',
     E'Pregnancy\nPacemaker, metal implants or IUD with copper (for abdominal treatment)\nRecent surgery',
     'High-intensity focused electromagnetic stimulation', '1600334129128-685c5582fd35', 'Smooth spa stones arranged on a client’s back', TRUE, FALSE, 92),
    ('body', 'Body Skin Tightening', 'body-skin-tightening',
     'Radiofrequency treatment to support firmer-looking skin on the arms, abdomen and knees.',
     'Controlled radiofrequency heats the deeper layers of the skin to support collagen remodelling. It is used for skin laxity after weight change or with age on areas such as the arms, abdomen and above the knees. Improvement is gradual over three months.',
     45, 'Course of 4 to 6, every 2 weeks', 'None', 200.00, FALSE,
     E'Firmer-looking skin over time\nGradual, natural-looking change\nComfortable warmth',
     E'Remove body lotion on the day\nHydrate well the day before',
     E'Avoid hot baths for 24 hours\nMoisturise daily',
     E'Pregnancy\nPacemaker or metal implants in the area\nBroken skin in the area',
     'Monopolar radiofrequency', '1600334089648-b0d9d3028eb2', 'Warm stones placed along a client’s spine', TRUE, FALSE, 90),
    ('body', 'Lymphatic Drainage Massage', 'lymphatic-drainage',
     'A gentle, rhythmic manual technique that supports the lymphatic system and eases a feeling of heaviness.',
     'Performed by hand with light, rhythmic movements, lymphatic drainage supports the natural circulation of lymph. Clients often book it to relieve a feeling of heaviness or puffiness, or alongside body treatments. It is not a substitute for medical treatment of lymphoedema.',
     60, 'Single session or course of 5', 'None', 110.00, FALSE,
     E'Eases a feeling of heaviness in the legs\nCan reduce the look of puffiness\nDeeply relaxing',
     E'Avoid a large meal before\nWear loose clothing',
     E'Drink water\nRest if you can for the evening',
     E'Acute infection or fever\nHeart failure or thrombosis\nActive cancer treatment without medical approval',
     'Manual lymphatic drainage (Vodder method)', '1556760544-74068565f05c', 'Amber oil bottles beside a therapist’s hands', TRUE, FALSE, 88),
    ('anti-aging', 'Radiofrequency Skin Tightening', 'radiofrequency-skin-tightening',
     'A comfortable, non-invasive facial treatment that supports firmness along the jawline and cheeks.',
     'Radiofrequency energy gently heats the deeper layers of facial skin to support collagen production. It is suited to early laxity along the jawline, cheeks and neck. There is no downtime, and improvement develops gradually over the weeks following a course.',
     45, 'Course of 4 to 6, every 2 weeks', 'None', 260.00, FALSE,
     E'Supports firmer-looking skin\nNo downtime\nGradual, natural-looking change',
     E'Arrive without make-up if possible\nTell us about any facial implants or fillers',
     E'Apply SPF daily\nAvoid saunas for 24 hours',
     E'Pregnancy\nPacemaker or metal implants in the face\nActive skin conditions in the area',
     'Multipolar radiofrequency', '1600428877878-1a0fd85beda8', 'Facial roller, gua sha stone and serum', TRUE, TRUE, 86),
    ('anti-aging', 'Anti-Aging Facial Program', 'anti-aging-facial-program',
     'A three-month program combining in-clinic treatments with a prescribed home routine.',
     'Your specialist assesses your skin and builds a progressive plan that can combine peels, radiofrequency and LED, adjusted at each visit. A home routine with retinoids and antioxidants supports the work done in clinic. The program includes progress photographs so we can review changes together.',
     60, '6 visits over 3 months', 'Depends on the treatments chosen', 890.00, TRUE,
     E'A plan built around your priorities\nFollowed by the same specialist\nCombines in-clinic and home care',
     E'Initial consultation with skin analysis\nBring a list of the products you use at home',
     E'Follow the written home routine\nDaily broad-spectrum SPF',
     E'Contraindications depend on the treatments selected and are reviewed at consultation',
     'Combination protocol: peels, radiofrequency, LED', '1617897903246-719242758050', 'Serum bottle beside eucalyptus on wood', TRUE, FALSE, 84),
    ('anti-aging', 'Neck & Décolleté Renewal', 'neck-decollete-renewal',
     'Targeted care for the delicate skin of the neck and décolleté: texture, tone and fine lines.',
     'The neck and décolleté are often exposed to the sun and overlooked in skincare. This treatment combines a gentle peel, radiofrequency and a nourishing mask to improve the look of texture and tone. It can be booked alone or as part of a facial program.',
     45, 'Course of 3 to 4, every 3 weeks', 'Mild redness for a few hours', 210.00, FALSE,
     E'Smoother-looking skin texture\nHelps even out tone\nComfortable and relaxing',
     E'Avoid sun and self-tan for a week before\nStop retinoids on the area 3 days before',
     E'SPF on the neck and chest daily\nAvoid perfume on the area for 24 hours',
     E'Pregnancy\nBroken or sunburnt skin in the area',
     'Gentle peel, radiofrequency, nourishing mask', '1601049541289-9b1b7bbbfe19', 'Fingertip taking cream from a jar', TRUE, FALSE, 82),
    ('skin-programs', 'Personalized Skin Program', 'personalized-skin-program',
     'A fully tailored plan after an in-depth skin analysis, reviewed with you at every visit.',
     'Your program starts with a detailed consultation and skin analysis. Together we set realistic goals and a timeline, then combine treatments and a home routine in the order that suits your skin. Each visit is a review: we adjust what is not working and tell you honestly what to expect.',
     60, '4 to 8 visits over 2 to 4 months', 'Depends on the treatments chosen', 650.00, TRUE,
     E'One plan, one specialist\nRealistic goals agreed together\nAdjusted at every visit',
     E'Initial consultation with skin analysis\nComplete the health questionnaire before your first visit',
     E'Follow the personalised home routine\nDaily SPF',
     E'Reviewed individually at consultation',
     'Skin analysis imaging, combination protocols', '1590439471364-192aa70c0b53', 'Spa flat lay with towel, brush and soap', TRUE, TRUE, 80),
    ('skin-programs', 'Acne-Prone Skin Program', 'acne-prone-skin-program',
     'A structured program for congested, blemish-prone skin, in coordination with your doctor when needed.',
     'Designed for adults with persistent congestion or breakouts. We combine clarifying facials, gentle peels and blue LED with a simplified home routine. For moderate to severe acne we recommend, and can coordinate with, a medical consultation, as prescription treatment may be more appropriate.',
     50, '6 visits over 12 weeks', 'Minimal', 520.00, TRUE,
     E'A clear, simple routine\nRegular professional extraction\nSupport for the look of post-blemish marks',
     E'Bring your current products to the first visit\nTell us about any prescribed treatments',
     E'Follow the home routine consistently\nAvoid touching or squeezing blemishes',
     E'Isotretinoin use (some treatments must wait)\nPregnancy (some actives are excluded)',
     'Clarifying facials, salicylic peels, blue LED', '1531299204812-e6d44d9a185c', 'Client relaxing with cucumber slices during a facial', TRUE, FALSE, 78),
    ('skin-programs', 'Pigmentation Program', 'pigmentation-program',
     'A progressive approach to uneven tone and dark spots, built around strict sun protection.',
     'Pigmentation has many causes and is easily triggered again by sun and heat. This program combines suitable peels or light treatments with targeted home care and a strict sun protection routine. Improvement is progressive; we will be clear with you about what is realistic for your skin type.',
     50, '5 to 6 visits over 4 months', 'Mild flaking possible', 690.00, TRUE,
     E'Helps even out the appearance of skin tone\nCan soften the look of dark spots\nA routine to help prevent recurrence',
     E'Consultation required to identify the type of pigmentation\nNo sun exposure or tanning for 4 weeks before',
     E'Strict SPF 50 every day, reapplied\nAvoid heat and saunas during the program',
     E'Pregnancy\nActive sun exposure planned during the program',
     'Selected peels or IPL with targeted topicals', '1612817288484-6f916006741a', 'Skincare products arranged with smooth pebbles', TRUE, FALSE, 76),
    ('skin-programs', 'Bridal Skin Preparation', 'bridal-skin-preparation',
     'A calm, timed plan in the months before your wedding, finishing with a radiance facial in the final week.',
     'Ideally started four to six months before the date. We plan treatments so that anything with downtime happens early, and finish with gentle radiance treatments in the final weeks. Trial treatments are never scheduled close to the day.',
     60, '5 visits over 4 to 6 months', 'Planned around your date', 780.00, TRUE,
     E'A timeline built backwards from your date\nNo surprises close to the day\nIncludes a final radiance facial',
     E'Book a consultation at least 4 months before the date if possible',
     E'Follow the home routine\nAvoid trying new products in the final month',
     E'Reviewed individually at consultation',
     'Combination of facials, light peels and LED', '1509967419530-da38b4704bc6', 'Portrait of a woman with natural, luminous skin', TRUE, FALSE, 74)
) AS v(category_slug, name, slug, short_description, description, duration, sessions, downtime, price, price_from,
       benefits, preparation, aftercare, contraindications, technology, photo, alt, available, featured, age)
JOIN treatment_categories c ON c.slug = v.category_slug;

