    ('deep-skin-cleansing', '1531299204812-e6d44d9a185c', 'Calming eye pads during a facial', 0),
    ('deep-skin-cleansing', '1540555700478-4be289fbecef', 'Cleanser and towel', 1),
    ('skin-hydration-ritual', '1601049541289-9b1b7bbbfe19', 'Hydrating cream', 0),
    ('skin-hydration-ritual', '1597931752949-98c74b5b159f', 'Moisturiser pump bottle', 1),
