INSERT INTO treatment_faqs (treatment_id, question, answer, position)
SELECT t.id, v.question, v.answer, v.position
FROM (VALUES
    ('signature-hydrafacial', 'Is it suitable for sensitive skin?', 'Usually, yes. Serums and suction are adjusted to your skin, and your therapist checks how it responds throughout. If your skin is reactive on the day, tell us before we start.', 0),
    ('signature-hydrafacial', 'How soon will I see a difference?', 'Many clients notice that their skin looks fresher straight after the treatment. Longer-term changes depend on your skin and routine, and vary from person to person.', 1),
    ('signature-hydrafacial', 'Can I wear make-up afterwards?', 'We recommend leaving the skin bare for the rest of the day, but light mineral make-up is fine if needed.', 2),
    ('chemical-peels', 'Will my skin peel visibly?', 'It depends on the peel. Light peels rarely cause visible peeling; medium-strength peels can cause flaking for 3 to 7 days. We will tell you what to expect before booking.', 0),
    ('chemical-peels', 'How many peels will I need?', 'Most concerns respond best to a course of 3 to 6 peels. Your specialist will suggest a plan after assessing your skin.', 1),
    ('chemical-peels', 'Can I have a peel in summer?', 'Lighter peels can be performed year-round with strict sun protection. Stronger peels are best planned in autumn and winter.', 2),
    ('microneedling', 'Does microneedling hurt?', 'A topical anaesthetic is applied 20 to 30 minutes beforehand, so most clients describe a light scratching sensation rather than pain.', 0),
    ('microneedling', 'When will I see results?', 'Skin renewal takes time. Changes in texture usually develop over the weeks after each session and continue across the course. Results vary between individuals.', 1),
    ('laser-hair-removal', 'Why do I need several sessions?', 'Hair grows in cycles and the laser only affects follicles in the active growth phase, so several sessions are needed to reach each follicle at the right time.', 0),
    ('laser-hair-removal', 'Is it suitable for all skin tones?', 'Our diode laser can treat a wide range of skin tones with appropriate settings. A patch test and consultation confirm what is safe for you.', 1),
    ('laser-skin-resurfacing', 'Who performs the treatment?', 'Laser resurfacing is performed by one of our physicians after a medical consultation.', 0),
    ('laser-skin-resurfacing', 'How much time off should I plan?', 'Plan for 5 to 7 days of visible redness and flaking. Most clients prefer to schedule it before a quiet week.', 1),
    ('body-contouring', 'Will I lose weight?', 'No. Body contouring is not a weight-loss treatment. It can improve the look of contour and skin firmness in targeted areas when combined with a balanced lifestyle.', 0),
    ('body-contouring', 'What does it feel like?', 'A deep warmth combined with a massage-like suction. Most clients find it comfortable.', 1),
    ('cellulite-treatment', 'Can cellulite be removed completely?', 'Cellulite can be improved but rarely removed completely. We will set realistic expectations together at your consultation.', 0),
    ('radiofrequency-skin-tightening', 'Is there any downtime?', 'No. You may look slightly flushed for an hour, then you can return to your normal activities.', 0),
    ('radiofrequency-skin-tightening', 'When will I see a change?', 'Collagen remodelling is gradual: changes typically develop over two to three months after a course. Individual results vary.', 1),
    ('personalized-skin-program', 'What happens at the first consultation?', 'We discuss your concerns, history and routine, analyse your skin and agree on goals and a timeline. There is no obligation to start the program.', 0),
    ('personalized-skin-program', 'Can the plan change along the way?', 'Yes. Each visit is a review, and we adjust treatments based on how your skin responds.', 1),
    ('pigmentation-program', 'Why is sun protection so important?', 'Pigmentation is easily stimulated by UV and visible light. Without strict daily protection, treatments are far less effective and spots often return.', 0),
    ('bridal-skin-preparation', 'When should I start?', 'Ideally four to six months before the date, so that any treatment with downtime happens well ahead of the day.', 0),
    ('led-light-therapy', 'Is LED safe for the eyes?', 'You wear protective goggles throughout. LED treatment does not use UV light.', 0),
    ('acne-prone-skin-program', 'Do I need to see a doctor?', 'For persistent, painful or scarring acne we recommend a medical consultation, as prescription treatment may be more appropriate. We can coordinate with your doctor.', 0)
) AS v(slug, question, answer, position)
JOIN treatments t ON t.slug = v.slug;

INSERT INTO specialists (name, slug, role, bio, photo, experience, specialties, instagram_url, linkedin_url, display_order) VALUES
    ('Dr. Hélène Marchetti', 'helene-marchetti', 'Medical Director, Aesthetic Physician',
     'Dr. Marchetti trained in general medicine before specialising in aesthetic medicine. She leads every medical consultation at Éloria and believes the most important part of her work is the conversation before any treatment: understanding what a client hopes for, and being honest about what is realistic.',
     pg_temp.u('1559839734-2b71ea197ec2', 900, 1125, TRUE), '16 years in aesthetic medicine',
     E'Medical consultations\nLaser resurfacing\nSkin quality programs', NULL, 'https://www.linkedin.com/', 1),
    ('Dr. Karim Benali', 'karim-benali', 'Aesthetic Physician, Laser & Light',
     'Dr. Benali focuses on laser and light-based treatments. He is known for careful, conservative settings and for explaining each step before he begins. He oversees our laser safety protocols and trains the team on new devices.',
     pg_temp.u('1612531385446-f7e6d131e1d0', 900, 1125, TRUE), '11 years in laser medicine',
     E'Laser hair removal\nIPL photorejuvenation\nPigmentation', NULL, 'https://www.linkedin.com/', 2),
    ('Camille Rousseau', 'camille-rousseau', 'Lead Aesthetic Nurse',
     'Camille coordinates our clinical treatments and follows clients through their programs. With a background in dermatology nursing, she brings a precise, reassuring approach to peels, microneedling and post-treatment care.',
     pg_temp.u('1594824476967-48c8b964273f', 900, 1125, TRUE), '9 years in dermatology nursing',
     E'Chemical peels\nMicroneedling\nAftercare follow-up', 'https://www.instagram.com/', NULL, 3),
    ('Inès Lefèvre', 'ines-lefevre', 'Senior Skin Therapist',
     'Inès designs our facial protocols and leads the Signature Hydrafacial. She has a gift for reading skin on the day and adapting a treatment in real time, and a calm presence clients often mention.',
     pg_temp.u('1580489944761-15a19d654956', 900, 1125, TRUE), '12 years as a skin therapist',
     E'Signature facials\nSensitive skin\nAcne-prone skin', 'https://www.instagram.com/', NULL, 4),
    ('Sophie Laurent', 'sophie-laurent', 'Body Treatment Specialist',
     'Sophie specialises in body treatments and manual lymphatic drainage. She sets clear, realistic goals with every client and combines devices with hands-on techniques for comfortable, effective sessions.',
     pg_temp.u('1508214751196-bcfd4ca60f91', 900, 1125, TRUE), '10 years in body therapies',
     E'Body contouring\nLymphatic drainage\nCellulite treatments', NULL, NULL, 5),
    ('Margaux Dubois', 'margaux-dubois', 'Client Experience Manager',
     'Margaux is often the first person you speak to. She organises consultations, answers questions about programs and pricing, and makes sure every visit runs calmly and on time.',
     pg_temp.u('1573496359142-b8d87734a5a2', 900, 1125, TRUE), '8 years in luxury hospitality',
     E'Consultation planning\nPrograms and pricing\nClient care', NULL, 'https://www.linkedin.com/', 6);

-- Demonstration before/after images live in the frontend at /demo/results (tight crops of placeholder photography,
-- not patient results). Every description says so; replace them with consented patient photographs.
INSERT INTO results (treatment_id, before_image_url, after_image_url, title, description, duration_label, featured, display_order)
SELECT t.id, '/demo/results/' || v.file || '-before.jpg', '/demo/results/' || v.file || '-after.jpg', v.title,
       v.description || ' Demonstration images for this preview site.', v.duration, v.featured, v.position
FROM (VALUES
    ('signature-hydrafacial', 'hydrafacial-radiance', 'Radiance after a Hydrafacial course', 'Dull, dehydrated skin treated with monthly Signature Hydrafacials. The skin appears more luminous and even.', '3 sessions over 3 months', TRUE, 1),
    ('chemical-peels', 'clarifying-peel', 'Smoother texture after peels', 'A course of light glycolic peels for uneven texture, combined with a simplified home routine.', '4 peels over 10 weeks', TRUE, 2),
    ('microneedling', 'microneedling-texture', 'Refined texture with microneedling', 'Microneedling for enlarged-looking pores and mild textural irregularities.', '3 sessions over 4 months', TRUE, 3),
    ('skin-hydration-ritual', 'hydration-glow', 'Comfort for dehydrated skin', 'Hydration Rituals for skin that felt tight after winter, with a barrier-repair routine at home.', '4 sessions over 8 weeks', FALSE, 4),
    ('pigmentation-program', 'even-tone-program', 'A more even tone', 'Pigmentation Program combining gentle peels with strict daily sun protection.', '5 visits over 4 months', TRUE, 5),
    ('body-contouring', 'body-contour', 'Body contouring course', 'Radiofrequency and vacuum therapy on the lower back and flanks, alongside regular activity.', '8 sessions over 8 weeks', FALSE, 6),
    ('radiofrequency-skin-tightening', 'jawline-rf', 'Jawline firmness with radiofrequency', 'Radiofrequency for early laxity along the jawline. Changes developed gradually after the course.', '5 sessions over 10 weeks', TRUE, 7),
    ('acne-prone-skin-program', 'clear-skin-program', 'Calmer, clearer skin', 'Acne-Prone Skin Program with clarifying facials, salicylic peels and blue LED.', '6 visits over 12 weeks', FALSE, 8)
) AS v(slug, file, title, description, duration, featured, position)
JOIN treatments t ON t.slug = v.slug;

