INSERT INTO testimonials (author_name, author_detail, quote, treatment_name, display_order, published) VALUES
    ('Claire M.', 'Client since 2024', 'What I valued most was the first consultation. Nobody tried to sell me anything; they explained what was realistic for my skin and built a plan around it.', 'Personalized Skin Program', 1, TRUE),
    ('Anaïs D.', 'Paris 16e', 'The Hydrafacial has become my monthly hour of calm. My skin looks rested and the team remembers exactly how it reacted last time.', 'Signature Hydrafacial', 2, TRUE),
    ('Julien R.', 'Client since 2025', 'I was nervous about laser treatment. Dr. Benali walked me through every step and the settings were adjusted after the patch test. Very reassuring.', 'Laser Hair Removal', 3, TRUE),
    ('Sofia L.', 'Neuilly-sur-Seine', 'Camille followed my peel course from start to finish. Clear instructions, quick answers when I had questions, and no pressure at any point.', 'Chemical Peels', 4, TRUE),
    ('Nathalie B.', 'Client since 2023', 'A beautiful place, but what keeps me coming back is the honesty. When a treatment wasn’t right for me, they told me so.', 'Anti-Aging Facial Program', 5, TRUE),
    ('Émilie T.', 'Paris 8e', 'I started my bridal program five months before the wedding. Everything was timed so that the last weeks were only gentle, glowing treatments.', 'Bridal Skin Preparation', 6, TRUE),
    ('Hugo P.', 'Client since 2025', 'Efficient, discreet and precise. The lymphatic drainage sessions with Sophie are the best I’ve had.', 'Lymphatic Drainage Massage', 7, TRUE);

