INSERT INTO contact_messages (name, email, phone, message, status, created_at, updated_at) VALUES
    ('Hélène Vasseur', 'helene.vasseur@example.com', '+33 6 14 25 36 47', 'Hello, do you offer gift vouchers for a facial? I would like to offer one for a birthday in two weeks.', 'NEW', now() - interval '3 hours', now() - interval '3 hours'),
    ('Romain Blanc', 'romain.blanc@example.com', NULL, 'Is laser hair removal possible on darker skin types with your device? I would like to know before booking a consultation.', 'NEW', now() - interval '20 hours', now() - interval '20 hours'),
    ('Laura Simon', 'laura.simon@example.com', '+33 7 36 47 58 69', 'Could you tell me whether the Personalized Skin Program can be paid in several instalments?', 'NEW', now() - interval '2 days', now() - interval '2 days'),
    ('Victor Chevalier', 'victor.chevalier@example.com', NULL, 'Thank you for the lovely welcome last week. Do you have parking nearby?', 'READ', now() - interval '5 days', now() - interval '4 days'),
    ('Océane Faure', 'oceane.faure@example.com', '+33 6 47 58 69 70', 'I am pregnant: which facials can I safely have during the second trimester?', 'READ', now() - interval '8 days', now() - interval '7 days'),
    ('Benoît Lambert', 'benoit.lambert@example.com', NULL, 'Do you work with corporate partnerships for employee wellbeing days?', 'ARCHIVED', now() - interval '20 days', now() - interval '18 days');
